    SAPODataConnectorProfileProperties.add_member(:o_auth_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: OAuthProperties, location_name: 'oAuthProperties', traits: {"smithy.api#documentation" => "<p> The SAPOData OAuth properties required for OAuth type authentication. </p>"}))
    SAPODataConnectorProfileProperties.add_member(:disable_sso, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'disableSSO', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>If you set this parameter to <code>true</code>, Amazon AppFlow bypasses the single\n      sign-on (SSO) settings in your SAP account when it accesses your SAP OData instance.</p>\n         <p>Whether you need this option depends on the types of credentials that you applied to your\n      SAP OData connection profile. If your profile uses basic authentication credentials, SAP SSO\n      can prevent Amazon AppFlow from connecting to your account with your username and\n      password. In this case, bypassing SSO makes it possible for Amazon AppFlow to connect\n      successfully. However, if your profile uses OAuth credentials, this parameter has no\n      affect.</p>"}))
