    SalesforceConnectorProfileCredentials.add_member(:access_token, Smithy::Schema::Shapes::ShapeRef.new(shape: AccessToken, location_name: 'accessToken', traits: {"smithy.api#documentation" => "<p> The credentials used to access protected Salesforce resources. </p>"}))
    SalesforceConnectorProfileCredentials.add_member(:refresh_token, Smithy::Schema::Shapes::ShapeRef.new(shape: RefreshToken, location_name: 'refreshToken', traits: {"smithy.api#documentation" => "<p> The credentials used to acquire new access tokens. </p>"}))
    SalesforceConnectorProfileCredentials.add_member(:o_auth_request, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectorOAuthRequest, location_name: 'oAuthRequest', traits: {"smithy.api#documentation" => "<p> The OAuth requirement needed to request security tokens from the connector endpoint.\n    </p>"}))
    SalesforceConnectorProfileCredentials.add_member(:client_credentials_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientCredentialsArn, location_name: 'clientCredentialsArn', traits: {"smithy.api#documentation" => "<p> The secret manager ARN, which contains the client ID and client secret of the connected\n      app. </p>"}))
    SalesforceConnectorProfileCredentials.add_member(:o_auth2_grant_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OAuth2GrantType, location_name: 'oAuth2GrantType', traits: {"smithy.api#documentation" => "<p>Specifies the OAuth 2.0 grant type that Amazon AppFlow uses when it requests an\n      access token from Salesforce. Amazon AppFlow requires an access token each time it\n      attempts to access your Salesforce records.</p>\n         <p>You can specify one of the following values:</p>\n         <dl>\n            <dt>AUTHORIZATION_CODE</dt>\n            <dd>\n               <p>Amazon AppFlow passes an authorization code when it requests the access token\n            from Salesforce. Amazon AppFlow receives the authorization code from Salesforce\n            after you log in to your Salesforce account and authorize Amazon AppFlow to access\n            your records.</p>\n            </dd>\n            <dt>JWT_BEARER</dt>\n            <dd>\n               <p>Amazon AppFlow passes a JSON web token (JWT) when it requests the access token\n            from Salesforce. You provide the JWT to Amazon AppFlow when you define the\n            connection to your Salesforce account. When you use this grant type, you don't need to\n            log in to your Salesforce account to authorize Amazon AppFlow to access your\n            records.</p>\n            </dd>\n         </dl>\n         <note>\n            <p>The CLIENT_CREDENTIALS value is not supported for Salesforce.</p>\n         </note>"}))
    SalesforceConnectorProfileCredentials.add_member(:jwt_token, Smithy::Schema::Shapes::ShapeRef.new(shape: JwtToken, location_name: 'jwtToken', traits: {"smithy.api#documentation" => "<p>A JSON web token (JWT) that authorizes Amazon AppFlow to access your Salesforce\n      records.</p>"}))
    SalesforceConnectorProfileCredentials.type = Types::SalesforceConnectorProfileCredentials
    SalesforceConnectorProfileProperties.add_member(:instance_url, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceUrl, location_name: 'instanceUrl', traits: {"smithy.api#documentation" => "<p> The location of the Salesforce resource. </p>"}))
    SalesforceConnectorProfileProperties.add_member(:is_sandbox_environment, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'isSandboxEnvironment', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p> Indicates whether the connector profile applies to a sandbox or production environment.\n    </p>"}))
    SalesforceConnectorProfileProperties.add_member(:use_private_link_for_metadata_and_authorization, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'usePrivateLinkForMetadataAndAuthorization', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>If the connection mode for the connector profile is private, this parameter sets whether\n        Amazon AppFlow uses the private network to send metadata and authorization calls to\n      Salesforce. Amazon AppFlow sends private calls through Amazon Web Services PrivateLink. These\n      calls travel through Amazon Web Services infrastructure without being exposed to the public\n      internet.</p>\n         <p>Set either of the following values:</p>\n         <dl>\n            <dt>true</dt>\n            <dd>\n               <p>Amazon AppFlow sends all calls to Salesforce over the private network.</p>\n               <p>These private calls are:</p>\n               <ul>\n                  <li>\n                     <p>Calls to get metadata about your Salesforce records. This metadata describes\n                your Salesforce objects and their fields.</p>\n                  </li>\n                  <li>\n                     <p>Calls to get or refresh access tokens that allow Amazon AppFlow to access\n                your Salesforce records.</p>\n                  </li>\n                  <li>\n                     <p>Calls to transfer your Salesforce records as part of a flow run.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>false</dt>\n            <dd>\n               <p>The default value. Amazon AppFlow sends some calls to Salesforce privately and\n            other calls over the public internet.</p>\n               <p>The public calls are: </p>\n               <ul>\n                  <li>\n                     <p>Calls to get metadata about your Salesforce records.</p>\n                  </li>\n                  <li>\n                     <p>Calls to get or refresh access tokens.</p>\n                  </li>\n               </ul>\n               <p>The private calls are:</p>\n               <ul>\n                  <li>\n                     <p>Calls to transfer your Salesforce records as part of a flow run.</p>\n                  </li>\n               </ul>\n            </dd>\n         </dl>"}))
    SalesforceConnectorProfileProperties.type = Types::SalesforceConnectorProfileProperties
    SalesforceDataTransferApi.add_member(:automatic, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AUTOMATIC', traits: {"smithy.api#enumValue" => "AUTOMATIC"}))
    SalesforceDataTransferApi.add_member(:bulkv2, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BULKV2', traits: {"smithy.api#enumValue" => "BULKV2"}))
    SalesforceDataTransferApi.add_member(:rest_sync, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'REST_SYNC', traits: {"smithy.api#enumValue" => "REST_SYNC"}))
    SalesforceDataTransferApiList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceDataTransferApi)
    SalesforceDestinationProperties.add_member(:object, Smithy::Schema::Shapes::ShapeRef.new(shape: Object, location_name: 'object', traits: {"smithy.api#documentation" => "<p> The object specified in the Salesforce flow destination. </p>", "smithy.api#required" => {}}))
    SalesforceDestinationProperties.add_member(:id_field_names, Smithy::Schema::Shapes::ShapeRef.new(shape: IdFieldNameList, location_name: 'idFieldNames', traits: {"smithy.api#documentation" => "<p> The name of the field that Amazon AppFlow uses as an ID when performing a write\n      operation such as update or delete. </p>"}))
    SalesforceDestinationProperties.add_member(:error_handling_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ErrorHandlingConfig, location_name: 'errorHandlingConfig', traits: {"smithy.api#documentation" => "<p> The settings that determine how Amazon AppFlow handles an error when placing data in\n      the Salesforce destination. For example, this setting would determine if the flow should fail\n      after one insertion error, or continue and attempt to insert every record regardless of the\n      initial failure. <code>ErrorHandlingConfig</code> is a part of the destination connector\n      details. </p>"}))
    SalesforceDestinationProperties.add_member(:write_operation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WriteOperationType, location_name: 'writeOperationType', traits: {"smithy.api#documentation" => "<p> This specifies the type of write operation to be performed in Salesforce. When the value\n      is <code>UPSERT</code>, then <code>idFieldNames</code> is required. </p>"}))
    SalesforceDestinationProperties.add_member(:data_transfer_api, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceDataTransferApi, location_name: 'dataTransferApi', traits: {"smithy.api#documentation" => "<p>Specifies which Salesforce API is used by Amazon AppFlow when your flow transfers\n      data to Salesforce.</p>\n         <dl>\n            <dt>AUTOMATIC</dt>\n            <dd>\n               <p>The default. Amazon AppFlow selects which API to use based on the number of\n            records that your flow transfers to Salesforce. If your flow transfers fewer than 1,000\n            records, Amazon AppFlow uses Salesforce REST API. If your flow transfers 1,000\n            records or more, Amazon AppFlow uses Salesforce Bulk API 2.0.</p>\n               <p>Each of these Salesforce APIs structures data differently. If Amazon AppFlow\n            selects the API automatically, be aware that, for recurring flows, the data output might\n            vary from one flow run to the next. For example, if a flow runs daily, it might use REST\n            API on one day to transfer 900 records, and it might use Bulk API 2.0 on the next day to\n            transfer 1,100 records. For each of these flow runs, the respective Salesforce API\n            formats the data differently. Some of the differences include how dates are formatted\n            and null values are represented. Also, Bulk API 2.0 doesn't transfer Salesforce compound\n            fields.</p>\n               <p>By choosing this option, you optimize flow performance for both small and large data\n            transfers, but the tradeoff is inconsistent formatting in the output.</p>\n            </dd>\n            <dt>BULKV2</dt>\n            <dd>\n               <p>Amazon AppFlow uses only Salesforce Bulk API 2.0. This API runs asynchronous\n            data transfers, and it's optimal for large sets of data. By choosing this option, you\n            ensure that your flow writes consistent output, but you optimize performance only for\n            large data transfers.</p>\n               <p>Note that Bulk API 2.0 does not transfer Salesforce compound fields.</p>\n            </dd>\n            <dt>REST_SYNC</dt>\n            <dd>\n               <p>Amazon AppFlow uses only Salesforce REST API. By choosing this option, you\n            ensure that your flow writes consistent output, but you decrease performance for large\n            data transfers that are better suited for Bulk API 2.0. In some cases, if your flow\n            attempts to transfer a vary large set of data, it might fail with a timed out\n            error.</p>\n            </dd>\n         </dl>"}))
    SalesforceDestinationProperties.type = Types::SalesforceDestinationProperties
    SalesforceMetadata.add_member(:o_auth_scopes, Smithy::Schema::Shapes::ShapeRef.new(shape: OAuthScopeList, location_name: 'oAuthScopes', traits: {"smithy.api#documentation" => "<p> The desired authorization scope for the Salesforce account. </p>"}))
    SalesforceMetadata.add_member(:data_transfer_apis, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceDataTransferApiList, location_name: 'dataTransferApis', traits: {"smithy.api#documentation" => "<p>The Salesforce APIs that you can have Amazon AppFlow use when your flows transfers\n      data to or from Salesforce.</p>"}))
    SalesforceMetadata.add_member(:oauth2_grant_types_supported, Smithy::Schema::Shapes::ShapeRef.new(shape: OAuth2GrantTypeSupportedList, location_name: 'oauth2GrantTypesSupported', traits: {"smithy.api#documentation" => "<p>The OAuth 2.0 grant types that Amazon AppFlow can use when it requests an access\n      token from Salesforce. Amazon AppFlow requires an access token each time it attempts to\n      access your Salesforce records.</p>\n         <dl>\n            <dt>AUTHORIZATION_CODE</dt>\n            <dd>\n               <p>Amazon AppFlow passes an authorization code when it requests the access token\n            from Salesforce. Amazon AppFlow receives the authorization code from Salesforce\n            after you log in to your Salesforce account and authorize Amazon AppFlow to access\n            your records.</p>\n            </dd>\n            <dt>JWT_BEARER</dt>\n            <dd>\n               <p>Amazon AppFlow passes a JSON web token (JWT) when it requests the access token\n            from Salesforce. You provide the JWT to Amazon AppFlow when you define the\n            connection to your Salesforce account. When you use this grant type, you don't need to\n            log in to your Salesforce account to authorize Amazon AppFlow to access your\n            records.</p>\n            </dd>\n         </dl>\n         <note>\n            <p>The CLIENT_CREDENTIALS value is not supported for Salesforce.</p>\n         </note>"}))
    SalesforceMetadata.type = Types::SalesforceMetadata
    SalesforceSourceProperties.add_member(:object, Smithy::Schema::Shapes::ShapeRef.new(shape: Object, location_name: 'object', traits: {"smithy.api#documentation" => "<p> The object specified in the Salesforce flow source. </p>", "smithy.api#required" => {}}))
    SalesforceSourceProperties.add_member(:enable_dynamic_field_update, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableDynamicFieldUpdate', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p> The flag that enables dynamic fetching of new (recently added) fields in the Salesforce\n      objects while running a flow. </p>"}))
    SalesforceSourceProperties.add_member(:include_deleted_records, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'includeDeletedRecords', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p> Indicates whether Amazon AppFlow includes deleted files in the flow run. </p>"}))
    SalesforceSourceProperties.add_member(:data_transfer_api, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceDataTransferApi, location_name: 'dataTransferApi', traits: {"smithy.api#documentation" => "<p>Specifies which Salesforce API is used by Amazon AppFlow when your flow transfers\n      data from Salesforce.</p>\n         <dl>\n            <dt>AUTOMATIC</dt>\n            <dd>\n               <p>The default. Amazon AppFlow selects which API to use based on the number of\n            records that your flow transfers from Salesforce. If your flow transfers fewer than\n            1,000,000 records, Amazon AppFlow uses Salesforce REST API. If your flow transfers\n            1,000,000 records or more, Amazon AppFlow uses Salesforce Bulk API 2.0.</p>\n               <p>Each of these Salesforce APIs structures data differently. If Amazon AppFlow\n            selects the API automatically, be aware that, for recurring flows, the data output might\n            vary from one flow run to the next. For example, if a flow runs daily, it might use REST\n            API on one day to transfer 900,000 records, and it might use Bulk API 2.0 on the next\n            day to transfer 1,100,000 records. For each of these flow runs, the respective\n            Salesforce API formats the data differently. Some of the differences include how dates\n            are formatted and null values are represented. Also, Bulk API 2.0 doesn't transfer\n            Salesforce compound fields.</p>\n               <p>By choosing this option, you optimize flow performance for both small and large data\n            transfers, but the tradeoff is inconsistent formatting in the output.</p>\n            </dd>\n            <dt>BULKV2</dt>\n            <dd>\n               <p>Amazon AppFlow uses only Salesforce Bulk API 2.0. This API runs asynchronous\n            data transfers, and it's optimal for large sets of data. By choosing this option, you\n            ensure that your flow writes consistent output, but you optimize performance only for\n            large data transfers.</p>\n               <p>Note that Bulk API 2.0 does not transfer Salesforce compound fields.</p>\n            </dd>\n            <dt>REST_SYNC</dt>\n            <dd>\n               <p>Amazon AppFlow uses only Salesforce REST API. By choosing this option, you\n            ensure that your flow writes consistent output, but you decrease performance for large\n            data transfers that are better suited for Bulk API 2.0. In some cases, if your flow\n            attempts to transfer a vary large set of data, it might fail wituh a timed out\n            error.</p>\n            </dd>\n         </dl>"}))
